const input = $json.body ?? $json;
const text = String(input.message ?? '').toLowerCase();
let output = '¡Hola! Soy el asistente de CocoEsencia. Puedo orientarte sobre jabones, pagos y rastreo.';
if (text.includes('pse') || text.includes('tarjeta') || text.includes('pago')) output = 'Puedes pagar con tarjeta o PSE mediante nuestra ventana segura de Wompi. La tienda no almacena tus datos financieros.';
if (text.includes('rastre') || text.includes('pedido')) output = 'Para rastrear tu pedido, ingresa el código COCO- recibido después de la compra en la sección Rastreo.';
if (text.includes('coco') || text.includes('ingrediente')) output = 'Nuestras fórmulas iniciales tienen aceite de coco como base. Consulta los ingredientes en la ficha de cada producto.';
return [{ json: { output } }];
